"use client";

import { useState } from "react";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { ChevronDown, Search } from "lucide-react";

const faqs = [
  {
    q: "How does the free tier work?",
    a: "The Free tier includes 1,000 build minutes per month, support for up to 3 team members, and basic monitoring for one project. No credit card required — just sign up and start shipping.",
  },
  {
    q: "Can I self-host the platform?",
    a: "Yes. Our Enterprise plan includes an on-premise option that runs on your own Kubernetes cluster. You get the full platform behind your firewall with dedicated support.",
  },
  {
    q: "What CI/CD providers do you support?",
    a: "We integrate natively with GitHub Actions, GitLab CI/CD, and Bitbucket Pipelines. You can also bring your own runner via our API for custom setups.",
  },
  {
    q: "How does pricing scale with my team?",
    a: "The Pro plan is $29/user/month with unlimited teams. As you grow, you only pay for active users — paused or deactivated members don't count toward your bill.",
  },
  {
    q: "What kind of support do you offer?",
    a: "Free and Pro plans include community support and email. Pro also gets priority support with a 4-hour SLA. Enterprise includes a dedicated support engineer and 1-hour SLA.",
  },
  {
    q: "Is my data secure on your platform?",
    a: "Absolutely. We are SOC 2 Type II certified, GDPR compliant, and encrypt data at rest and in transit. All logs are immutable and retained per your policy. SSO and audit trails are available on Enterprise.",
  },
  {
    q: "Can I migrate from my current CI/CD tool?",
    a: "Yes. We provide migration scripts for GitHub Actions, GitLab CI, CircleCI, and Jenkins. Most teams are fully migrated within a week with zero downtime.",
  },
  {
    q: "Do you offer discounts for startups or nonprofits?",
    a: "We do. Qualified startups can apply for our Startup Program (50% off Pro for the first year). Nonprofits receive a 30% discount on any plan. Contact our sales team to apply.",
  },
];

export function Faq() {
  const [openIndex, setOpenIndex] = useState<number | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const reduce = useReducedMotion();

  const filtered = searchQuery.trim()
    ? faqs.filter(
        (faq) =>
          faq.q.toLowerCase().includes(searchQuery.toLowerCase()) ||
          faq.a.toLowerCase().includes(searchQuery.toLowerCase()),
      )
    : faqs;

  return (
    <section id="faq" className="py-24 md:py-32 border-t border-[#27272a]">
      <div className="max-w-3xl mx-auto px-4">
        <div className="text-center mb-12">
          <span className="inline-flex px-3 py-1 rounded-full text-xs font-medium bg-brand-500/10 text-brand-400 border border-brand-500/20 mb-4">
            FAQ
          </span>
          <h2 className="text-3xl md:text-4xl lg:text-5xl font-bold tracking-tight">
            Got questions?
          </h2>
          <p className="mt-4 text-[#a1a1aa] max-w-xl mx-auto">
            We&apos;ve got answers. Can&apos;t find what you&apos;re looking for?
            Reach out to our support team.
          </p>
        </div>

        {/* Search */}
        <div className="relative mb-8">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-[#7a7a82] pointer-events-none" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value);
              setOpenIndex(null);
            }}
            placeholder="Search questions..."
            className="w-full pl-10 pr-4 py-2.5 rounded-xl bg-[#18181b] border border-[#27272a] text-sm text-[#fafafa] placeholder:text-[#7a7a82] focus:outline-none focus:border-brand-500/50 transition-colors"
          />
        </div>

        {/* FAQ List */}
