"use client";

import { useRef, useState, useEffect } from "react";
import { motion, useReducedMotion } from "motion/react";

const stats = [
  { label: "Deployments/month", value: 12_500_000, suffix: "+" },
  { label: "Engineering teams", value: 34_000, suffix: "+" },
  { label: "Avg. deployment time", value: 2.4, prefix: "<", suffix: "m" },
  { label: "Uptime SLA", value: 99.99, suffix: "%" },
];

function useCountUp(end: number, duration: number, started: boolean) {
  const [current, setCurrent] = useState(0);
  const reduce = useReducedMotion();

  useEffect(() => {
    if (!started || reduce) {
      setCurrent(end);
      return;
    }

    let startTime: number | null = null;
    let raf: number;

    const step = (now: number) => {
      if (!startTime) startTime = now;
      const elapsed = now - startTime;
      const progress = Math.min(elapsed / duration, 1);
      // Ease-out cubic
      const eased = 1 - Math.pow(1 - progress, 3);
      setCurrent(Math.floor(eased * end));

      if (progress < 1) {
        raf = requestAnimationFrame(step);
      } else {
        setCurrent(end);
      }
    };

    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [end, duration, started, reduce]);

  return current;
}

function formatNumber(n: number): string {
  if (n >= 1_000_000) return (n / 1_000_000).toFixed(1);
  return n.toLocaleString();
}

function StatCard({
  label,
  value,
  prefix,
  suffix,
  index,
  inView,
}: {
  label: string;
  value: number;
  prefix?: string;
  suffix?: string;
  index: number;
  inView: boolean;
}) {
  const count = useCountUp(value, 2000 + index * 200, inView);

  return (
    <motion.div
      initial={{ opacity: 0, y: 24 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, amount: 0.3 }}
      transition={{
        duration: 0.6,
        delay: index * 0.1,
        ease: [0.16, 1, 0.3, 1],
      }}
      className="flex flex-col items-center text-center p-6"
    >
      <span className="text-4xl md:text-5xl font-bold tracking-tight text-[#fafafa]">
        {prefix || ""}
        {formatNumber(count)}
        {suffix || ""}
      </span>
      <span className="mt-2 text-sm text-[#a1a1aa]">{label}</span>
    </motion.div>
  );
}

export function Stats() {
  const ref = useRef<HTMLDivElement>(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          observer.disconnect();
        }
      },
      { threshold: 0.3 },
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <section
      ref={ref}
      className="py-20 md:py-24 border-t border-[#27272a] relative overflow-hidden"
    >
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-brand-500/5 via-transparent to-transparent pointer-events-none" />
      <div className="relative z-10 max-w-5xl mx-auto px-4">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 md:gap-8">
          {stats.map((stat, i) => (
            <StatCard key={stat.label} {...stat} index={i} inView={inView} />
          ))}
        </div>
      </div>
    </section>
  );
}

